from __future__ import annotations

from unittest.mock import patch

import pytest

from app.core.config import Settings
from app.libs.identity.service import FirebaseIdentityService
from tests.libs.identity.conftest import FakeAuthModule


def _dev_service() -> FirebaseIdentityService:
    return FirebaseIdentityService(Settings(firebase_auth_disabled=True))


# --- Positive ------------------------------------------------------------------


def test_create_user_under_dev_bypass_returns_deterministic_value_with_zero_sdk_calls():
    fake_auth = FakeAuthModule()
    svc = _dev_service()
    with patch("app.libs.identity.service.auth", fake_auth):
        uid = svc.create_user("dev@example.com")
    assert uid == "dev-dev@example.com"
    assert fake_auth.create_user_calls == []


def test_generate_set_password_link_dev_bypass_is_deterministic_with_zero_sdk_calls():
    fake_auth = FakeAuthModule()
    svc = _dev_service()
    with patch("app.libs.identity.service.auth", fake_auth):
        link = svc.generate_set_password_link("dev@example.com")
    assert link == "https://dev.invalid/set-password?email=dev@example.com"
    assert fake_auth.generate_password_reset_link_calls == []


