@pytest.mark.parametrize("email", ["a@example.com", "b@example.com", "unicode-ñ@example.com"])
def test_same_email_always_yields_same_synthetic_uid_deterministic(email):
    svc = _dev_service()
    with patch("app.libs.identity.service.auth", FakeAuthModule()):
        uid1 = svc.create_user(email)
        uid2 = svc.create_user(email)
