def test_different_emails_yield_different_synthetic_uids():
    svc = _dev_service()
    with patch("app.libs.identity.service.auth", FakeAuthModule()):
        uid_a = svc.create_user("a@example.com")
        uid_b = svc.create_user("b@example.com")
    assert uid_a != uid_b


